function closeCalendars(except) { document.querySelectorAll('.jalali-field').forEach(field => { if (field === except) return; field.querySelector('.jalali-picker').hidden = true; field.querySelector('.calendar-toggle').setAttribute('aria-expanded','false'); }); }
function toggleCalendar(field) { const picker = field.querySelector('.jalali-picker'); const opening = picker.hidden; closeCalendars(); if (opening) { const iso = field.querySelector('[type=hidden]').value || today(); const p = persianParts(iso); drawCalendar(field,p.year,p.month); picker.classList.toggle('align-left',field.getBoundingClientRect().right < Math.min(300,innerWidth-65)+16); picker.hidden = false; field.querySelector('.calendar-toggle').setAttribute('aria-expanded','true'); } }
function drawCalendar(field,year,month) {
 const picker = field.querySelector('.jalali-picker');
 picker.dataset.year = year; picker.dataset.month = month;
 const selected = field.querySelector('[type=hidden]').value;
 const calendar = persianMonth(year,month);
 picker.innerHTML = `<div class="calendar-header"><button type="button" data-action="calendar-move" data-move="-1" aria-label="ماه قبل">›</button><select aria-label="ماه شمسی" data-calendar-month>${months.map((name,i) => `<option value="${i+1}" ${month === i+1 ? 'selected' : ''}>${name}</option>`).join('')}</select><select aria-label="سال شمسی" data-calendar-year>${Array.from({length:401},(_,i) => i+1200).map(y => `<option value="${y}" ${year === y ? 'selected' : ''}>${fa(y).replaceAll('٬','')}</option>`).join('')}</select><button type="button" data-action="calendar-move" data-move="1" aria-label="ماه بعد">‹</button></div><div class="calendar-week">${['ش','ی','د','س','چ','پ','ج'].map(d => `<span>${d}</span>`).join('')}</div><div class="calendar-days">${'<span></span>'.repeat(calendar.offset)}${calendar.days.map((iso,i) => `<button type="button" data-action="calendar-day" data-date="${iso}" class="${iso === selected ? 'selected' : ''} ${iso === today() ? 'is-today' : ''}" aria-label="${formatPersianDate(iso)}" aria-pressed="${iso === selected}">${fa(i+1)}</button>`).join('')}</div><div class="calendar-footer"><button type="button" data-action="calendar-today">امروز</button>${!field.querySelector('.jalali-input').required ? '<button type="button" data-action="calendar-clear">پاک کردن</button>' : ''}<span>${fa(calendar.days.length)} روز</span></div>`;
}
function moveCalendar(field,delta) { const picker = field.querySelector('.jalali-picker'); let year = Number(picker.dataset.year), month = Number(picker.dataset.month)+delta; if (month < 1) { month=12; year--; } if (month > 12) { month=1; year++; } if (year >= 1200 && year <= 1600) drawCalendar(field,year,month); }
function chooseDate(field,iso) { const input = field.querySelector('.jalali-input'); input.value = formatPersianDate(iso); input.setCustomValidity(''); field.querySelector('[type=hidden]').value = iso; closeCalendars(); input.focus(); }
document.addEventListener('input',e => { if (!e.target.matches('.jalali-input')) return; const iso = parsePersianDate(e.target.value); const blank = !e.target.value.trim(); e.target.setCustomValidity(iso || (blank && !e.target.required) ? '' : 'تاریخ شمسی معتبر مانند ۱۴۰۵/۰۸/۰۷ وارد کنید.'); e.target.closest('.jalali-field').querySelector('[type=hidden]').value = iso || ''; });
document.addEventListener('change',e => { if (e.target.matches('[data-calendar-year],[data-calendar-month]')) { const field = e.target.closest('.jalali-field'); drawCalendar(field,Number(field.querySelector('[data-calendar-year]').value),Number(field.querySelector('[data-calendar-month]').value)); } });
document.addEventListener('pointerdown',e => { if (!e.target.closest('.jalali-field')) closeCalendars(); });
