function heading(title, description, buttons = '') { return `<div class="heading"><div><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${buttons}</div></div>`; }
function metric(label, value, unit, glyph, foot) { return `<article class="metric"><div class="metric-top"><span>${label}</span><span class="metric-icon">${icon(glyph)}</span></div><div class="metric-value"><strong>${fa(value)}</strong><span>${unit}</span></div><div class="metric-foot">${foot}</div></article>`; }
function totals(transactions = state.transactions) { const income = transactions.filter(t => t.kind === 'income').reduce((s,t) => s + t.amount, 0); const expense = transactions.filter(t => t.kind === 'expense').reduce((s,t) => s + t.amount, 0); return { income, expense, net:income - expense }; }
function dashboard() {
 const { income, expense } = totals();
 const active = state.invoices.filter(i => i.kind === 'invoice' && i.status === 'issued');
 const receivable = active.reduce((s,i) => s + i.total - i.paid, 0);
 const overdue = active.filter(i => invoiceStatus(i) === 'overdue').length;
 return `${heading('نمای کلی کسب‌وکار', 'هر آنچه برای یک روز کاری بهتر نیاز دارید.', button('export','خروجی تراکنش‌ها','secondary','download') + button('new-invoice','صدور فاکتور'))}<section class="welcome"><div><h2>روزتان بخیر، ${esc(session.user.name.split(' ')[0])} ${icon('spark')}</h2><p>${overdue ? `${fa(overdue)} فاکتور از سررسید گذشته است؛ امروز فرصتی برای پیگیری پرداخت‌هاست.` : 'همه‌چیز برای یک روز پربار آماده است. به کسب‌وکارتان با خیال راحت برسید.'}</p></div><span class="welcome-label"><i class="dot"></i>فضای کاری شخصی شما</span></section><section class="metrics">${metric('مجموع دریافتی‌ها',income,'تومان','wallet','<b>دریافت واقعی</b> از ابتدای فعالیت')}${metric('مطالبات باز',receivable,'تومان','clock',`<b>${fa(active.filter(i => i.total > i.paid).length)} فاکتور</b> در انتظار تسویه`)}${metric('مجموع هزینه‌ها',expense,'تومان','chart','هزینه‌های ثبت‌شده کسب‌وکار')}${metric('مشتریان شما',state.customers.length,'مشتری','users','همراهان مسیر رشد کسب‌وکار شما')}</section><div class="grid-main"><section class="card"><div class="card-head"><div><h2>جریان مالی کسب‌وکار</h2><p>روند دریافت‌ها و هزینه‌ها در ۳۰ روز گذشته · تومان</p></div><div class="legend"><span><i style="background:#497e58"></i>دریافت</span><span><i style="background:#d5b672"></i>هزینه</span></div></div><div class="card-body">${chart()}</div></section><section class="card"><div class="card-head"><div><h2>وضعیت فاکتورها</h2><p>فاکتورهای فروش صادرشده</p></div>${icon('invoice')}</div>${invoiceRing(active)}</section></div><div class="bottom-grid"><section class="card"><div class="card-head"><div><h2>آخرین فاکتورها</h2><p>یک نگاه به تازه‌ترین فعالیت‌های فروش</p></div><button class="link-btn" data-page="invoices">مشاهده همه ${icon('arrow')}</button></div>${invoiceTable(state.invoices.slice(0,5), true)}</section><div><section class="quick-card"><div>${icon('spark')}<h2>از کار خوب، تا دریافت به‌موقع</h2><p>فاکتور حرفه‌ای بسازید و مسیر پرداخت هر پروژه را روشن نگه دارید.</p></div>${button('new-invoice','یک فاکتور تازه بسازید','', 'plus')}</section><section class="card" style="margin-top:20px"><div class="card-head"><h2>تازه‌ترین رویدادها</h2>${icon('clock')}</div><div class="card-body">${state.audit.slice(0,3).map(a => `<div class="activity">${icon('check')}<div>${esc(a.action)}<small>${localDate(a.created_at.replace(' ','T') + 'Z')}</small></div></div>`).join('') || '<p class="stat-note">فعالیت‌های شما اینجا ثبت می‌شوند.</p>'}</div></section></div></div><footer class="footer"><span>وَندار؛ نظم بیشتر، خیال آسوده‌تر.</span><span>مبالغ به تومان · گزارش‌ها بر مبنای دریافت و پرداخت</span></footer>`;
}
function chart() {
 const days = Array.from({ length:30 }, (_,i) => { const d = new Date(today() + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate()-29+i); return d.toISOString().slice(0,10); });
 const series = ['income','expense'].map(kind => days.map(d => state.transactions.filter(t => t.kind === kind && t.date === d).reduce((s,t) => s+t.amount,0)));
 const max = Math.max(...series.flat(), 1);
 const points = a => a.map((v,i) => `${(i/29*580+15).toFixed(1)},${(165-v/max*135).toFixed(1)}`).join(' ');
 return `<div class="chart" aria-label="نمودار جریان نقدی؛ جزئیات در گزارش‌های مالی"><svg viewBox="0 0 610 190" preserveAspectRatio="none" role="img"><title>دریافت‌ها و هزینه‌های ۳۰ روز گذشته</title><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#69956c" stop-opacity=".18"/><stop offset="100%" stop-color="#69956c" stop-opacity="0"/></linearGradient></defs>${[30,75,120,165].map(y => `<line x1="15" x2="595" y1="${y}" y2="${y}" stroke="#e9ede5" stroke-dasharray="4 6"/>`).join('')}<polygon points="15,175 ${points(series[0])} 595,175" fill="url(#area)"/><polyline points="${points(series[0])}" fill="none" stroke="#54805c" stroke-width="2.5"/><polyline points="${points(series[1])}" fill="none" stroke="#d4b577" stroke-width="2"/></svg>${max === 1 && !series.flat().some(Boolean) ? '<div class="chart-empty">با ثبت اولین تراکنش، نمودار شما شکل می‌گیرد.</div>' : ''}<div class="chart-labels">${[0,7,14,21,29].map(i => `<span>${localDate(days[i])}</span>`).join('')}</div></div>`;
}
function invoiceRing(active) { const counts = ['paid','partial','issued','overdue'].map(s => active.filter(i => invoiceStatus(i) === s).length); const colors = ['#6f9565','#d5b573','#c6cfc0','#cf8275']; let offset = 0; const circumference = 402.12; const segments = counts.map((n,i) => { const len = n/(active.length || 1)*circumference; const svg = `<circle cx="80" cy="80" r="64" fill="none" stroke="${colors[i]}" stroke-width="16" stroke-dasharray="${len} ${circumference-len}" stroke-dashoffset="${-offset}"/>`; offset += len; return svg; }).join(''); return `<div class="ring-wrap"><svg viewBox="0 0 160 160" role="img" aria-label="توزیع وضعیت فاکتورها"><circle cx="80" cy="80" r="64" fill="none" stroke="#f0f3ec" stroke-width="16"/>${segments}</svg><div class="ring-center"><strong>${fa(active.length)}</strong><small>فاکتور فروش</small></div></div><div class="status-list">${counts.map((n,i) => `<div class="status-line"><span><i style="background:${colors[i]}"></i>${statuses[['paid','partial','issued','overdue'][i]]}</span><b>${fa(n)} <small>فاکتور</small></b></div>`).join('')}</div>`; }
function invoiceTable(list, compact = false) { if (!list.length) return empty('هنوز فاکتوری ثبت نشده', 'از دکمه «صدور فاکتور» اولین فاکتورتان را بسازید.'); return `<div class="table-wrap"><table><thead><tr><th>شماره فاکتور</th><th>مشتری</th>${compact ? '' : '<th>نوع / تاریخ</th>'}<th>مبلغ کل</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${list.map(i => `<tr><td><b dir="ltr">${esc(i.number)}</b></td><td><div class="customer-cell"><span class="customer-avatar">${esc(i.customer_snapshot.name.slice(0,1))}</span><div>${esc(i.customer_snapshot.name)}<small>${esc(i.customer_snapshot.company)}</small></div></div></td>${compact ? '' : `<td>${kinds[i.kind]}<small style="display:block">${localDate(i.date)}</small></td>`}<td>${money(i.total)}${!compact && i.paid ? `<small style="display:block">دریافت: ${fa(i.paid)}</small>` : ''}</td><td>${badge(invoiceStatus(i))}</td><td><div class="row-actions"><button class="icon-btn" data-action="view-invoice" data-id="${i.id}" title="مشاهده و چاپ" aria-label="مشاهده ${esc(i.number)}">${icon('eye')}</button>${!compact ? `<button class="icon-btn" data-action="edit-invoice" data-id="${i.id}" title="ویرایش" aria-label="ویرایش فاکتور">${icon('edit')}</button>${i.kind === 'invoice' && i.status === 'issued' && i.paid < i.total ? `<button class="icon-btn" data-action="invoice-payment" data-id="${i.id}" title="ثبت دریافت" aria-label="ثبت دریافت">${icon('wallet')}</button>` : ''}` : ''}</div></td></tr>`).join('')}</tbody></table></div>`; }
function searchBar(placeholder, filters = '') { return `<div class="toolbar"><label class="searchbox">${icon('search')}<input id="search" aria-label="جست‌وجو" placeholder="${placeholder}"></label><div class="filters">${filters}</div></div>`; }
function customersPage() { return `${heading('مشتریان', 'ارتباط‌های ارزشمند کسب‌وکارتان را یک‌جا مدیریت کنید.', button('new-customer','مشتری جدید'))}<section class="card">${searchBar('جست‌وجوی نام، شرکت، تلفن…')}<div id="results">${customerTable(state.customers)}</div></section>`; }
function customerTable(list) { return list.length ? `<div class="table-wrap"><table><thead><tr><th>نام مشتری / شرکت</th><th>تلفن</th><th>ایمیل</th><th>مانده حساب</th><th>عملیات</th></tr></thead><tbody>${list.map(c => `<tr><td><div class="customer-cell"><span class="customer-avatar">${esc(c.name[0])}</span><div>${esc(c.name)}<small>${esc(c.company)}</small></div></div></td><td dir="ltr">${esc(c.phone) || '—'}</td><td>${esc(c.email) || '—'}</td><td>${money(c.balance)}</td><td><div class="row-actions"><button class="icon-btn" data-action="edit-customer" data-id="${c.id}" aria-label="ویرایش مشتری">${icon('edit')}</button><button class="icon-btn" data-action="delete-customer" data-id="${c.id}" aria-label="حذف مشتری">${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>` : empty('مشتری‌ای پیدا نشد', 'مشتریان جدید را ثبت کنید تا صدور فاکتور ساده‌تر شود.', 'users'); }
function servicesPage() { return `${heading('خدمات', 'خدمت‌ها و قیمت‌های رایج را برای صدور سریع فاکتور ثبت کنید.', button('new-service','خدمت جدید'))}<section class="card">${state.services.length ? `<div class="table-wrap"><table><thead><tr><th>نام خدمت</th><th>قیمت پیشنهادی</th><th>عملیات</th></tr></thead><tbody>${state.services.map(s => `<tr><td>${esc(s.name)}</td><td>${money(s.price)}</td><td><div class="row-actions"><button class="icon-btn" data-action="edit-service" data-id="${s.id}" aria-label="ویرایش خدمت ${esc(s.name)}">${icon('edit')}</button><button class="icon-btn" data-action="delete-service" data-id="${s.id}" aria-label="حذف خدمت ${esc(s.name)}">${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>` : empty('خدمتی ثبت نشده', 'خدمات پرتکرار خود را با قیمت پیشنهادی ثبت کنید.', 'grid')}</section>`; }
function invoicesPage() { return `${heading('فاکتورها', 'از پیشنهاد قیمت تا تسویه؛ مسیر فروش را دنبال کنید.', button('new-invoice','صدور فاکتور'))}<section class="card">${searchBar('جست‌وجوی شماره یا نام مشتری…', `<select id="status-filter" aria-label="فیلتر وضعیت"><option value="">همه وضعیت‌ها</option>${Object.entries(statuses).map(([k,v]) => `<option value="${k}">${v}</option>`).join('')}</select><select id="kind-filter" aria-label="فیلتر نوع"><option value="">همه انواع</option>${Object.entries(kinds).map(([k,v]) => `<option value="${k}">${v}</option>`).join('')}</select>`)}<div id="results">${invoiceTable(state.invoices)}</div></section>`; }
function transactionTable(list) { return list.length ? `<div class="table-wrap"><table><thead><tr><th>شرح / دسته</th><th>تاریخ</th><th>نوع</th><th>مبلغ</th><th>روش / پیگیری</th><th>فاکتور</th><th>عملیات</th></tr></thead><tbody>${list.map(t => `<tr><td>${esc(t.category)}<small style="display:block">${esc(t.notes.slice(0,60))}</small></td><td>${localDate(t.date)}</td><td>${badge(t.kind, t.kind === 'income' ? 'دریافت' : 'هزینه')}</td><td>${money(t.amount)}</td><td>${methods[t.method]}<small style="display:block">${esc(t.reference)}</small></td><td>${t.invoice_number ? `<button class="link-btn" data-action="view-invoice" data-id="${t.invoice_id}">${esc(t.invoice_number)}</button>` : '—'}</td><td><button class="icon-btn" data-action="delete-transaction" data-id="${t.id}" aria-label="حذف تراکنش برای اصلاح">${icon('trash')}</button></td></tr>`).join('')}</tbody></table></div>` : empty('تراکنشی برای نمایش نیست', 'دریافت‌ها و هزینه‌ها را ثبت کنید تا حساب‌هایتان به‌روز بماند.', 'wallet'); }
function transactionsPage() { const {income,expense,net} = totals(); return `${heading('دریافت‌ها و هزینه‌ها', 'ثبت شفاف هر مبلغی که وارد کسب‌وکارتان یا از آن خارج می‌شود.', button('new-expense','ثبت هزینه','secondary','plus') + button('new-income','ثبت دریافت'))}<div class="metrics" style="grid-template-columns:repeat(3,1fr)">${metric('دریافت',income,'تومان','wallet','کل مبالغ دریافت‌شده')}${metric('هزینه',expense,'تومان','chart','کل مبالغ پرداخت‌شده')}${metric('خالص جریان نقدی',net,'تومان','bank','دریافت منهای هزینه')}</div><section class="card">${searchBar('جست‌وجوی دسته، شرح، شماره پیگیری…','<select id="type-filter" aria-label="نوع تراکنش"><option value="">همه تراکنش‌ها</option><option value="income">دریافت‌ها</option><option value="expense">هزینه‌ها</option></select>')}<div id="results">${transactionTable(state.transactions)}</div></section>`; }
function reportsPage() { const list = state.transactions.filter(t => (!reportRange.start || t.date >= reportRange.start) && (!reportRange.end || t.date <= reportRange.end)); const {income,expense,net} = totals(list); const categories = {}; for (const t of list) { const k = t.kind + ':' + t.category; categories[k] ||= { category:t.category, kind:t.kind, amount:0, count:0 }; categories[k].amount += t.amount; categories[k].count++; } return `${heading('گزارش‌های مالی', 'گزارش جریان نقدی و مطالبات، برای تصمیم‌های روشن‌تر.',button('export','CSV تراکنش‌ها','secondary','download','data-type="transactions"') + button('export','CSV فاکتورها','secondary','download','data-type="invoices"') + button('export','CSV مشتریان','secondary','download','data-type="customers"'))}<section class="card" style="margin-bottom:22px"><form data-form="report" class="report-controls">${field('از تاریخ','start',reportRange.start,'date')}${field('تا تاریخ','end',reportRange.end,'date')}<button class="btn primary" type="submit">اعمال بازه</button>${button('reset-report','همه زمان‌ها','secondary','calendar')}</form><p class="report-summary">بازه را با تقویم شمسی انتخاب کنید یا تاریخ را به صورت ۱۴۰۵/۰۸/۰۷ وارد کنید.</p></section><div class="metrics" style="grid-template-columns:repeat(3,1fr)">${metric('دریافت در بازه',income,'تومان','wallet',`${fa(list.filter(t => t.kind === 'income').length)} تراکنش دریافت`)}${metric('هزینه در بازه',expense,'تومان','chart',`${fa(list.filter(t => t.kind === 'expense').length)} تراکنش هزینه`)}${metric('خالص جریان نقدی',net,'تومان','bank','مبنای نقدی؛ شامل مطالبات وصول‌نشده نیست')}</div><div class="two-col"><section class="card"><div class="card-head"><h2>تفکیک دسته‌ها در بازه</h2>${icon('chart')}</div>${Object.keys(categories).length ? `<div class="table-wrap"><table><thead><tr><th>دسته</th><th>نوع</th><th>تعداد</th><th>مبلغ</th></tr></thead><tbody>${Object.values(categories).map(c => `<tr><td>${esc(c.category)}</td><td>${badge(c.kind,c.kind === 'income' ? 'دریافت' : 'هزینه')}</td><td>${fa(c.count)}</td><td>${money(c.amount)}</td></tr>`).join('')}</tbody></table></div>` : empty('هنوز داده‌ای در این بازه نیست','با ثبت تراکنش، گزارش‌ها ساخته می‌شوند.','chart')}</section><section class="card"><div class="card-head"><h2>مطالبات فعلی مشتریان</h2>${icon('users')}</div><div class="report-summary">این بخش مانده فعلی همه زمان‌ها را نشان می‌دهد.</div>${state.customers.some(c => c.balance > 0) ? `<div class="table-wrap"><table><thead><tr><th>مشتری</th><th>مانده دریافتنی</th></tr></thead><tbody>${state.customers.filter(c => c.balance > 0).map(c => `<tr><td>${esc(c.name)}</td><td>${money(c.balance)}</td></tr>`).join('')}</tbody></table></div>` : empty('مطالبه بازی ندارید','مانده فاکتورهای فروش اینجا نمایش داده می‌شود.','check')}</section></div><div class="notice">گزارش‌ها بر مبنای نقدی هستند؛ این نسخه دفتر کل دوطرفه، اظهارنامه مالیاتی و اتصال به سامانه مؤدیان ندارد.</div>`; }
function settingsPage() { const s = state.settings; return `${heading('تنظیمات کسب‌وکار','هویت کسب‌وکار شما روی فاکتورها دیده می‌شود.')}<div class="settings-grid"><section class="card"><h2>اطلاعات کسب‌وکار</h2><form data-form="settings"><div class="form-grid">${field('نام کسب‌وکار','business',s.business,'text','required maxlength="150"')}${field('نام صاحب کسب‌وکار','owner',s.owner,'text','maxlength="100"')}${field('شماره تماس','phone',s.phone,'tel','maxlength="40"')}${field('شماره شبا / اطلاعات پرداخت','iban',s.iban,'text','maxlength="50" dir="ltr"')}${textarea('نشانی','address',s.address)}${field('پیشوند شماره فاکتور','invoice_prefix',s.invoice_prefix,'text','required pattern="[A-Za-z0-9-]+" maxlength="15" dir="ltr"')}${selectField('قالب پیش‌فرض فاکتور','template',templates,s.template)}</div>${actions('ذخیره تنظیمات')}</form></section><div><section class="card logo-settings"><h2>لوگوی کسب‌وکار</h2><div class="logo-current">${businessLogo(s)}</div><form data-form="logo"><label class="field">فایل لوگو<input type="file" name="logo" accept="image/png,image/jpeg,image/webp" required></label><p class="muted" style="font-size:11px;margin-top:8px">PNG، JPEG یا WebP ثابت؛ حداکثر ۲ مگابایت و ۱۰ میلیون پیکسل. لوگو در قالب‌های فاکتور نمایش داده می‌شود.</p><div class="form-actions"><button class="btn primary" type="submit">ذخیره لوگو</button>${s.logo_id ? button('remove-logo','حذف لوگوی فعلی','secondary','trash') : ''}</div></form><p class="stat-note">تغییر لوگو، فاکتورهای قبلی را تغییر نمی‌دهد.</p></section><section class="card logo-settings" style="margin-top:22px"><h2>مهر و امضای فروشنده</h2><div class="logo-current">${s.seal_id ? `<img class="seal-image" src="/api/logo/${esc(s.seal_id)}" alt="مهر و امضا">` : 'هنوز تصویری ثبت نشده است.'}</div><form data-form="seal"><label class="field">تصویر شفاف مهر و امضا<input type="file" name="seal" accept="image/png,image/webp" required></label><p class="muted" style="font-size:11px;margin-top:8px">PNG یا WebP با زمینه شفاف، حداکثر ۲ مگابایت. روی فاکتورهای تازه ثبت می‌شود.</p><div class="form-actions"><button class="btn primary" type="submit">ذخیره مهر و امضا</button>${s.seal_id ? button('remove-seal','حذف تصویر فعلی','secondary','trash') : ''}</div></form></section><section class="card" style="margin-top:22px"><h2>پوسته محیط کاری</h2><p class="muted" style="font-size:12px">پوسته روی این مرورگر ذخیره می‌شود و ظاهر اسناد چاپی را تغییر نمی‌دهد.</p><div class="theme-cards">${Object.entries(uiThemes).map(([k,v]) => `<button type="button" data-action="set-theme" data-theme="${k}" aria-pressed="${theme() === k}"><span class="theme-swatch">${themeSwatches[k].map(c => `<i style="background:${c}"></i>`).join('')}</span>${v}</button>`).join('')}</div></section><section class="card" style="margin-top:22px"><h2>قالب‌های فاکتور</h2><p class="muted" style="font-size:12px">چهار قالب رسمی و چهار قالب غیررسمی. قالب هر فاکتور را هنگام صدور هم می‌توانید جدا انتخاب کنید.</p>${Object.entries(templates).map(([k,v]) => `<div class="security-item"><div class="security-title">${icon('invoice')}<h3>${v}</h3>${s.template === k ? badge('paid','پیش‌فرض') : ''}</div><p>${templateNotes[k]}</p></div>`).join('')}</section><div class="notice">همه مبالغ به تومان ثبت می‌شوند. تغییر مشخصات مشتری، اطلاعات ذخیره‌شده در فاکتورهای قبلی را تغییر نمی‌دهد.</div></div></div>`; }
function securityPage() { return `${heading('امنیت حساب','کنترل دسترسی و نگهداری از اطلاعات کسب‌وکار.')}<div class="settings-grid"><section class="card"><h2>دسترسی و محافظت</h2><div class="security-item"><div class="security-title">${icon('shield')}<h3>ورود دومرحله‌ای</h3>${badge(session.user.twoFactor ? 'paid' : 'overdue',session.user.twoFactor ? 'فعال' : 'غیرفعال')}</div><p>با برنامه‌هایی مثل Google Authenticator یا Microsoft Authenticator، یک لایه محافظت به حساب اضافه کنید.</p>${!session.user.twoFactor ? button('setup-totp','فعال‌سازی ورود دومرحله‌ای','primary','shield') : '<div class="notice">برای ورود علاوه بر گذرواژه، کد برنامه یا کد بازیابی لازم است. کدهای بازیابی را در جایی امن نگه دارید.</div>'}</div><div class="security-item"><div class="security-title">${icon('lock')}<h3>تغییر گذرواژه</h3></div><p>پس از تغییر، سایر نشست‌های فعال از حساب خارج می‌شوند.</p>${button('change-password','تغییر گذرواژه','secondary','lock')}</div><div class="security-item"><div class="security-title">${icon('download')}<h3>پشتیبان پایگاه داده</h3></div><p>نسخه‌ای از اطلاعات مالی دانلود کنید. این فایل حاوی اطلاعات حساس مشتریان است؛ آن را رمزگذاری‌شده نگه دارید.</p>${button('backup','دریافت پشتیبان','secondary','download')}<p>برای بازیابی کامل ورود دومرحله‌ای، مدیر سرور باید فایل encryption.key را نیز جداگانه و امن پشتیبان بگیرد.</p></div></section><section class="card"><h2>رویدادهای اخیر حساب</h2><p class="muted" style="font-size:11px;margin-bottom:15px">ثبت ۲۰۰ رویداد آخر برای بررسی فعالیت‌ها</p><div style="max-height:540px;overflow:auto">${state.audit.map(a => `<div class="activity">${icon('check')}<div>${esc(a.action)}<small>${localDate(a.created_at.replace(' ','T') + 'Z')} · ${esc(a.details.slice(0,45))}</small></div></div>`).join('')}</div></section></div>`; }
function renderPage() { return ({ dashboard, customers:customersPage, services:servicesPage, invoices:invoicesPage, transactions:transactionsPage, reports:reportsPage, settings:settingsPage, security:securityPage }[page] || dashboard)(); }
async function navigate(next) { if (!session.authenticated) return; page = ['dashboard','customers','services','invoices','transactions','reports','settings','security'].includes(next) ? next : 'dashboard'; location.hash = page; shell(); }

function customerForm(id) { const c = state.customers.find(c => c.id === Number(id)) || {}; openModal(c.id ? 'ویرایش مشتری' : 'مشتری جدید', `<form data-form="customer" data-id="${c.id || ''}"><div class="form-grid">${field('نام مشتری *','name',c.name,'text','required maxlength="150"')}${field('نام شرکت','company',c.company,'text','maxlength="150"')}${field('موبایل','phone',c.phone,'tel','inputmode="tel" maxlength="11" pattern="09[0-9۰-۹٠-٩]{9}" placeholder="09123456789" dir="ltr"')}${field('ایمیل','email',c.email,'email','maxlength="200" dir="ltr"')}${field('شناسه ملی / کد اقتصادی','national_id',c.national_id,'text','maxlength="40"','span-2')}${textarea('نشانی','address',c.address)}${textarea('یادداشت خصوصی','notes',c.notes)}</div>${actions(c.id ? 'ذخیره تغییرات' : 'ثبت مشتری')}</form>`); }
function serviceForm(id) { const s = state.services.find(s => s.id === Number(id)) || {}; openModal(s.id ? 'ویرایش خدمت' : 'خدمت جدید', `<form data-form="service" data-id="${s.id || ''}"><div class="form-grid">${field('نام خدمت *','name',s.name,'text','required maxlength="500"')}${field('قیمت پیشنهادی (تومان) *','price',s.price ?? 0,'text','required data-money inputmode="numeric"')}</div><p class="muted">قیمت را هنگام صدور هر فاکتور می‌توانید تغییر دهید؛ فاکتورهای قبلی ثابت می‌مانند.</p>${actions(s.id ? 'ذخیره تغییرات' : 'ثبت خدمت')}</form>`); modal.querySelectorAll('[data-money]').forEach(updateMoney); }
function lineItem(item = {}) { return `<div class="line-item">${field('شرح خدمت *','description',item.description,'text','required maxlength="500" list="item-descriptions" autocomplete="off"')}${field('تعداد *','quantity',item.quantity ?? 1,'number','required min="1" max="1000000" step="1"')}${field('قیمت واحد (تومان) *','price',item.price ?? 0,'text','required data-money inputmode="numeric"')}<button class="icon-btn" type="button" data-action="remove-line" aria-label="حذف ردیف">${icon('trash')}</button></div>`; }
function invoiceForm(id, clone = false) { if (!state.customers.length) { toast('ابتدا یک مشتری ثبت کنید.'); customerForm(); return; } const source = state.invoices.find(i => i.id === Number(id)) || {}; const i = clone ? { ...source, id:0, version:1, status:'issued', date:today(), due_date:futureDate(), paid:0 } : source; if (i.id && (i.status === 'void' || i.paid > 0)) { toast('فاکتور باطل یا دارای دریافت قابل ویرایش نیست.', true); return; } const descriptions = [...new Set([...state.services.map(s => s.name), ...state.invoices.flatMap(v => v.items.map(it => it.description)).slice(0, 200)])]; openModal(i.id ? `ویرایش ${esc(i.number)}` : clone ? `رونوشت از ${esc(source.number)}` : 'صدور فاکتور جدید', `<form data-form="invoice" data-id="${i.id || ''}" data-version="${i.version || 1}"><datalist id="item-descriptions">${descriptions.map(d => `<option value="${esc(d)}"></option>`).join('')}</datalist><div class="form-grid">${selectField('مشتری *','customer_id',Object.fromEntries(state.customers.map(c => [c.id,c.name + (c.company ? ' · ' + c.company : '')])),i.customer_id || state.customers[0].id)}${selectField('نوع سند','kind',kinds,i.kind || 'invoice')}${field('تاریخ صدور','date',i.date || today(),'date','required')}${field('سررسید','due_date',i.due_date || futureDate(),'date','required')}</div><div class="line-items"><h3>خدمات و اقلام فاکتور</h3><div id="line-items">${(i.items || [{}]).map(lineItem).join('')}</div>${button('add-line','افزودن ردیف','secondary small','plus')}</div><div class="form-grid">${field('تخفیف کل (تومان)','discount',i.discount || 0,'text','required data-money inputmode="numeric"')}${field('مالیات (%)','tax_rate',i.tax_rate || 0,'number','min="0" max="100" step="1" required')}${selectField('وضعیت','status',{ draft:'پیش‌نویس', issued:'صادرشده' },i.status || 'issued')}${selectField('قالب فاکتور','template',templates,i.template || state.settings.template)}${textarea('توضیحات و شرایط پرداخت','notes',i.notes)}</div><div class="totals-box" id="invoice-totals"></div><small class="muted">فاکتور فروش برای دریافت وجه است؛ پیش‌فاکتور و پیشنهاد قیمت وارد مطالبات نمی‌شوند.</small>${actions(i.id ? 'ذخیره تغییرات' : 'ثبت فاکتور')}</form>`, true); updateInvoiceTotals(); modal.querySelectorAll('[data-money]').forEach(updateMoney); }
function updateInvoiceTotals() { const form = modal.querySelector('[data-form=invoice]'); if (!form) return; const subtotal = [...form.querySelectorAll('.line-item')].reduce((s,row) => s + Number(row.querySelector('[name=quantity]').value)*moneyValue(row.querySelector('[name=price]').value),0); const discount = moneyValue(form.elements.discount.value); const tax = Math.round((subtotal - discount)*Number(form.elements.tax_rate.value)/100); form.querySelector('#invoice-totals').innerHTML = `<div><span>جمع اقلام</span><span>${money(subtotal)}</span></div><div><span>تخفیف</span><span>${money(discount)}</span></div><div><span>مالیات</span><span>${money(tax)}</span></div><div class="grand-total"><span>مبلغ نهایی</span><span>${money(subtotal-discount+tax)}</span></div>`; }
function transactionForm(kind, invoiceId) { const payable = state.invoices.filter(i => i.kind === 'invoice' && i.status === 'issued' && i.paid < i.total); const i = payable.find(i => i.id === Number(invoiceId)); openModal(kind === 'income' ? 'ثبت دریافت' : 'ثبت هزینه', `<form data-form="transaction"><input type="hidden" name="kind" value="${kind}"><div class="form-grid">${kind === 'income' ? selectField('مرتبط با فاکتور','invoice_id',{ '':'دریافت مستقل (بدون فاکتور)', ...Object.fromEntries(payable.map(i => [i.id,`${i.number} · ${i.customer_snapshot.name} · مانده ${fa(i.total-i.paid)}`])) },invoiceId || '','span-2') : ''}${field('مبلغ (تومان) *','amount',i ? i.total-i.paid : '','text','required data-money inputmode="numeric"')}${field('تاریخ *','date',today(),'date','required')}${field('دسته *','category',kind === 'income' ? 'خدمات نرم‌افزار' : 'هزینه کسب‌وکار','text','required maxlength="100"')}${selectField('روش پرداخت','method',methods,'transfer')}${field('شماره پیگیری','reference','','text','maxlength="100"','span-2')}${textarea('یادداشت','notes')}</div>${actions(kind === 'income' ? 'ثبت دریافت' : 'ثبت هزینه')}</form>`); modal.querySelectorAll('[data-money]').forEach(updateMoney); }
function viewInvoice(id) { const i = state.invoices.find(i => i.id === Number(id)); if (!i) return; const s = i.seller_snapshot?.business ? i.seller_snapshot : state.settings; const c = i.customer_snapshot; const doc = i.template === 'landscape' ? landscapeInvoice(i,s) : `<article class="invoice-preview ${esc(i.template)}"><div class="invoice-banner"><div><div class="brand">${businessLogo(s)}<div><h2>${esc(s.business)}</h2><small>${esc(s.owner)}</small></div></div></div><div><h2>${kinds[i.kind]}</h2><p dir="ltr">${esc(i.number)}</p>${badge(invoiceStatus(i))}</div></div><div class="parties"><div><h3>فروشنده: ${esc(s.business)}</h3><p>${esc(s.address)}</p><p>${esc(s.phone)}</p></div><div><h3>خریدار: ${esc(c.name)}</h3><p>${esc(c.company)} ${esc(c.national_id)}</p><p>${esc(c.address)}</p><p>${esc(c.phone)} · ${esc(c.email)}</p></div></div><div class="invoice-meta"><div><p>تاریخ صدور: ${localDate(i.date)}</p><p>تاریخ سررسید: ${localDate(i.due_date)}</p><p>شماره سند: <b dir="ltr">${esc(i.number)}</b></p></div><img class="invoice-qr" src="/api/invoices/${i.id}/qr" alt="کد QR خلاصه سند" loading="lazy"></div><table class="invoice-items"><thead><tr><th>ردیف</th><th>شرح خدمت</th><th>تعداد</th><th>قیمت واحد (تومان)</th><th>مبلغ (تومان)</th></tr></thead><tbody>${i.items.map((item,index) => `<tr><td>${fa(index+1)}</td><td>${esc(item.description)}</td><td>${fa(item.quantity)}</td><td>${fa(item.price)}</td><td>${fa(item.quantity*item.price)}</td></tr>`).join('')}</tbody></table><div class="totals-box"><div><span>جمع اقلام</span><span>${money(i.subtotal)}</span></div><div><span>تخفیف</span><span>${money(i.discount)}</span></div><div><span>مالیات (${fa(i.tax_rate)}٪)</span><span>${money(i.tax)}</span></div><div class="grand-total"><span>مبلغ کل</span><span>${money(i.total)}</span></div>${i.kind === 'invoice' ? `<div><span>دریافت‌شده</span><span>${money(i.paid)}</span></div><div><span>مانده</span><span>${money(i.total-i.paid)}</span></div>` : ''}</div><div class="amount-words">مبلغ کل به حروف: <b>${esc(persianWords(i.total))} تومان</b></div><p class="notes">${esc(i.notes)}</p>${s.iban ? `<p class="notes">اطلاعات پرداخت: <b dir="ltr">${esc(s.iban)}</b></p>` : ''}<section class="invoice-signatures"><div><strong>مهر و امضای فروشنده</strong><span>${esc(s.owner || s.business)}</span>${s.seal_id ? `<img class="seal-image" src="/api/logo/${esc(s.seal_id)}" alt="مهر و امضای فروشنده">` : '<i></i>'}</div><div><strong>محل امضای خریدار</strong><span>${esc(c.name)}</span><i></i></div></section><p class="notes">این سند، صورتحساب الکترونیکی سامانه مؤدیان نیست. مبالغ به تومان است.</p></article>`; openModal('مشاهده فاکتور', doc, true); if (i.template === 'landscape') modal.style.maxWidth = '1200px'; modal.querySelector('.modal-body').style.padding = '0'; modal.insertAdjacentHTML('beforeend', `<div class="print-actions">${button('download-pdf','دانلود PDF','primary','download',`data-id="${i.id}"`)}${button('print','چاپ','secondary','print')}${button('edit-invoice','ویرایش','secondary','edit',`data-id="${i.id}"`)}${button('clone-invoice','رونوشت تازه','secondary','invoice',`data-id="${i.id}"`)}${i.status !== 'void' && !i.paid ? button('void-invoice','ابطال فاکتور','danger','close',`data-id="${i.id}"`) : ''}</div>`); }
function confirmDialog(title, message, action, id) { openModal(title, `<p>${esc(message)}</p><div class="form-actions">${button('close','انصراف','secondary','close')}${button(action,'تأیید','danger','check',`data-id="${id}"`)}</div>`); }
function passwordDialog(kind) { openModal({ 'setup-totp':'فعال‌سازی ورود دومرحله‌ای', 'change-password':'تغییر گذرواژه', backup:'دریافت پشتیبان امن' }[kind], `<form data-form="${kind}">${field('گذرواژه فعلی','password','','password','required autocomplete="current-password" maxlength="128"')}${kind === 'change-password' ? field('گذرواژه جدید (حداقل ۸ نویسه)','new_password','','password','required minlength="8" maxlength="128" autocomplete="new-password"') + field('تکرار گذرواژه جدید','confirm_password','','password','required minlength="8" maxlength="128" autocomplete="new-password"') : ''}${actions('ادامه')}</form>`); }
function filterResults() { const term = document.querySelector('#search')?.value.trim().toLowerCase() || ''; const el = document.querySelector('#results'); if (!el) return; if (page === 'customers') el.innerHTML = customerTable(state.customers.filter(c => [c.name,c.company,c.phone,c.email].some(v => v.toLowerCase().includes(term)))); if (page === 'invoices') { const status = document.querySelector('#status-filter').value; const kind = document.querySelector('#kind-filter').value; el.innerHTML = invoiceTable(state.invoices.filter(i => [i.number,i.customer_snapshot.name].some(v => v.toLowerCase().includes(term)) && (!status || invoiceStatus(i) === status) && (!kind || i.kind === kind))); } if (page === 'transactions') { const kind = document.querySelector('#type-filter').value; el.innerHTML = transactionTable(state.transactions.filter(t => [t.category,t.notes,t.reference,t.invoice_number || ''].some(v => v.toLowerCase().includes(term)) && (!kind || t.kind === kind))); } }
async function refresh(message) { await load(); shell(); if (message) toast(message); }

document.addEventListener('click', async e => {
 const el = e.target.closest('[data-action],[data-page]'); if (!el || el.disabled) return;
 if (el.dataset.page) return navigate(el.dataset.page);
 const {action,id} = el.dataset;
 try {
  switch (action) {
   case 'close': modal.close(); break;
   case 'menu': document.querySelector('.sidebar').classList.toggle('open'); break;
   case 'logout': await api('/logout','POST',{}); session = await api('/session'); modal.close(); authView(); break;
   case 'new-customer': customerForm(); break;
   case 'edit-customer': customerForm(id); break;
   case 'delete-customer': confirmDialog('حذف مشتری','مشتری فقط در صورت نداشتن فاکتور حذف می‌شود. ادامه می‌دهید؟','confirm-delete-customer',id); break;
   case 'confirm-delete-customer': await api('/customers/'+id,'DELETE'); modal.close(); await refresh('مشتری حذف شد.'); break;
   case 'new-service': serviceForm(); break;
   case 'edit-service': serviceForm(id); break;
   case 'delete-service': confirmDialog('حذف خدمت','خدمت از فهرست حذف می‌شود؛ فاکتورهای قبلی تغییر نمی‌کنند. ادامه می‌دهید؟','confirm-delete-service',id); break;
   case 'confirm-delete-service': await api('/services/'+id,'DELETE'); modal.close(); await refresh('خدمت حذف شد.'); break;
   case 'new-invoice': invoiceForm(); break;
   case 'edit-invoice': invoiceForm(id); break;
   case 'clone-invoice': invoiceForm(id, true); break;
   case 'set-theme': applyTheme(el.dataset.theme); shell(); break;
   case 'view-invoice': viewInvoice(id); break;
   case 'add-line': if (modal.querySelectorAll('.line-item').length >= 100) throw new Error('حداکثر ۱۰۰ ردیف مجاز است.'); document.querySelector('#line-items').insertAdjacentHTML('beforeend',lineItem()); updateInvoiceTotals(); break;
   case 'remove-line': if (modal.querySelectorAll('.line-item').length <= 1) throw new Error('حداقل یک ردیف لازم است.'); el.closest('.line-item').remove(); updateInvoiceTotals(); break;
   case 'void-invoice': confirmDialog('ابطال فاکتور','فاکتور باطل‌شده دیگر قابل ویرایش نیست. ادامه می‌دهید؟','confirm-void',id); break;
   case 'confirm-void': await api('/invoices/'+id+'/void','POST',{}); modal.close(); await refresh('فاکتور باطل شد.'); break;
   case 'new-income': transactionForm('income'); break;
   case 'new-expense': transactionForm('expense'); break;
   case 'invoice-payment': transactionForm('income',id); break;
   case 'delete-transaction': confirmDialog('اصلاح تراکنش','این تراکنش حذف و مانده فاکتور مرتبط دوباره محاسبه می‌شود. جزئیات حذف در رویدادها می‌ماند. ادامه می‌دهید؟','confirm-delete-transaction',id); break;
   case 'confirm-delete-transaction': await api('/transactions/'+id,'DELETE'); modal.close(); await refresh('تراکنش حذف و مانده‌ها اصلاح شد.'); break;
   case 'export': window.location.assign('/api/export?type=' + (el.dataset.type || 'transactions')); break;
   case 'reset-report': reportRange = {start:'',end:''}; shell(); break;
   case 'print': window.print(); break;
   case 'download-pdf': { const invoice=state.invoices.find(i => i.id === Number(id)); if (!invoice) throw new Error('فاکتور پیدا نشد.'); await downloadInvoicePdf(invoice,invoice.seller_snapshot?.business ? invoice.seller_snapshot : state.settings); break; }
   case 'toggle-password': { const input=el.parentElement.querySelector('input'); input.type=input.type === 'password' ? 'text' : 'password'; el.setAttribute('aria-pressed',String(input.type === 'text')); el.setAttribute('aria-label',input.type === 'text' ? 'پنهان کردن گذرواژه' : 'نمایش گذرواژه'); break; }
   case 'setup-totp': case 'change-password': case 'backup': passwordDialog(action); break;
   case 'remove-logo': await api('/logo','DELETE'); await refresh('لوگو از تنظیمات فعلی حذف شد؛ لوگوی اسناد قبلی محفوظ است.'); break;
   case 'remove-seal': await api('/seal','DELETE'); await refresh('مهر و امضای فعلی حذف شد؛ اسناد قبلی محفوظ‌اند.'); break;
   case 'calendar-toggle': toggleCalendar(el.closest('.jalali-field')); break;
   case 'calendar-move': moveCalendar(el.closest('.jalali-field'),Number(el.dataset.move)); break;
   case 'calendar-day': chooseDate(el.closest('.jalali-field'),el.dataset.date); break;
   case 'calendar-today': chooseDate(el.closest('.jalali-field'),today()); break;
   case 'calendar-clear': chooseDate(el.closest('.jalali-field'),''); break;
   case 'copy-codes': { const codes = [...modal.querySelectorAll('.recovery-codes span')].map(el => el.textContent).join('\n'); await navigator.clipboard.writeText(codes); toast('کدهای بازیابی کپی شد.'); break; }
  }
 } catch (error) { toast(error.message,true); }
});
document.addEventListener('input', e => { if (e.target.matches('[data-money]')) updateMoney(e.target); if (e.target.matches('input[name=phone]')) e.target.value = normalizeDigits(e.target.value).replace(/\D/g, '').slice(0,11); if (e.target.matches('textarea[name=notes], textarea[name=address], input[name=description]')) { const start=e.target.selectionStart; e.target.value=digitsFa(e.target.value); e.target.setSelectionRange(start,start); } if (e.target.closest('[data-form=invoice]')) updateInvoiceTotals(); if (e.target.id === 'search') filterResults(); });
document.addEventListener('change', e => { if (e.target.id === 'theme') applyTheme(e.target.value); if (['status-filter','kind-filter','type-filter'].includes(e.target.id)) filterResults(); if (e.target.name === 'description' && e.target.closest('[data-form=invoice]')) { const service = state.services.find(s => s.name === e.target.value.trim()); if (service) { e.target.closest('.line-item').querySelector('[name=price]').value = service.price; updateInvoiceTotals(); } } if (e.target.name === 'invoice_id') { const i = state.invoices.find(i => i.id === Number(e.target.value)); if (i) { e.target.form.elements.amount.value = i.total-i.paid; updateMoney(e.target.form.elements.amount); } } });
